/bin/bash -c "python3 - <<'PY'
# Evaluate the published constraints on a two-layer chain u -> v.
P = {'u':[0,1], 'v':[1,0]}
Z = {'u':[1,1], 'v':[1,0]}
for i in range(2):
    print('stage', i+1, '6a',all(Z[x][i]>=P[x][i] for x in P), '6b',Z['v'][i]<=Z['u'][i], '6c',Z['v'][i]<=P['v'][i]-P['u'][i]+1)
print('7a',all(sum(row)==1 for row in P.values()))
print('7b',all(sum(P[x][i] for x in P)>=1 for i in range(2)))
print('Eq. 4 coefficient for the only edge:',P['u'][0]*P['v'][1])
PY"
